-- Thunder Bluff pass (Four, 2026-11-14). Compared every Thunder Bluff spawn (zone 1638) with TrinityCore TDB 7.3.5.
--
-- 1) "Baine pezuña de sangre" 130773: a Spanish-named copy of Baine Bloodhoof (faction 35, level 1, no gossip) from a
--    BFA scene, spawned twice in the city: next to the real Baine 36648 in his hut and on the Hunter Rise side
--    (guids 6740131, 6740132). TDB has neither. Spawns removed, template name in English.
DELETE FROM `creature` WHERE `guid` IN (6740131,6740132);
DELETE FROM `creature_addon` WHERE `guid` IN (6740131,6740132);
UPDATE `creature_template` SET `name`='Baine Bloodhoof' WHERE `entry`=130773;

-- 2) Patrols. Our Thunder Bluff walkers and fliers were sniffed snapshots standing where the sniff caught them:
--    13 Thunder Bluff Wind Riders 51372 hanging still in the air, 7 Bluffwatchers 3084 and 1 Honor Guard 3083 on
--    spots no TDB guard stands, two copies each of Bluff Runner Windstrider 10881 and Chepi 8361, and Hunters
--    Sagewind 14440 and Ragetotem 14441 off their routes. Replaced by TDB 7.3.5's spawns and waypoint paths:
--    5 wind rider patrols (two with two wingmen in formation), 6 Bluffwatcher patrols (one is our existing guard
--    260098, which stands on its start point), 1 Honor Guard, Windstrider, Chepi and the two hunters. The other
--    18 Bluffwatchers and 5 Honor Guards already match TDB's posts and are unchanged.
DELETE FROM `creature` WHERE `guid` IN (235499,260079,260105,260104,260252,235636,260092,260097,260251,260331,260487,262284,235586,235633,235634,235635,260244,260245,260246,260327,260329,260333,260334,260335,260392,235587,260205);
DELETE FROM `creature_addon` WHERE `guid` IN (235499,260079,260105,260104,260252,235636,260092,260097,260251,260331,260487,262284,235586,235633,235634,235635,260244,260245,260246,260327,260329,260333,260334,260335,260392,235587,260205);
DELETE FROM `creature` WHERE `guid` BETWEEN 735400003 AND 735400021;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 735400003 AND 735400021 OR `guid` IN (260098);
DELETE FROM `creature_formations` WHERE `leaderGUID` BETWEEN 735400003 AND 735400021;
DELETE FROM `waypoint_data` WHERE `id` IN (735400003,735400004,735400005,735400006,735400007,735400008,735400009,735400010,735400011,735400012,735400013,735400016,735400017,735400018,735400021,735400200);
UPDATE `creature` SET `MovementType`=2, `spawndist`=0 WHERE `guid`=260098;

